    if ((registro.type === 1 || registro.type === 28) && !ips.includes(registro.data)) ips.push(registro.data);
  }
}

if (ips.length === 0) {
  const naoExiste = respostaIPv4.Status === 3;
  return [{
    json: {
      ...alvo,
      ok: false,
      motivo: naoExiste
