// Nó "Processar resultados": calcula a nota e os achados automáticos A PARTIR DOS CABEÇALHOS REAIS.
// A nota não depende da IA (a IA pode errar ou inventar); o texto da IA entra só como análise complementar.
const dados = $('Tratar resposta').last().json;
const cab = dados.cabecalhos ?? {};
const ehHttps = String(dados.urlFinal).startsWith('https://');

function textoDaIA(nomeDoNo) {
  let json;
  try {
    json = $(nomeDoNo).last().json;
  } catch (erro) {
    return { ok: false, texto: 'A análise da IA não foi executada.' };
  }
  if (typeof json.output === 'string' && json.output.trim()) return { ok: true, texto: json.output.trim() };
  const erro = json.error?.message ?? json.error ?? 'resposta vazia';
  return { ok: false, texto: `A análise da IA não está disponível (${erro}). Confira a credencial do Google Gemini no n8n.` };
}

function valor(nome) {
  const v = cab[nome];
  if (v === undefined || v === null) return '';
  return Array.isArray(v) ? v.join(', ') : String(v);
}

const CABECALHOS = [
  'content-security-policy',
  'strict-transport-security',
  'x-content-type-options',
  'x-frame-options',
  'referrer-policy',
  'permissions-policy',
  'cross-origin-opener-policy',
  'cross-origin-embedder-policy',
  'cross-origin-resource-policy',
  'x-permitted-cross-domain-policies',
  'x-xss-protection',
];
const status = {};
for (const nome of CABECALHOS) status[nome] = { presente: valor(nome) !== '', valor: valor(nome) };

const csp = status['content-security-policy'].valor.toLowerCase();
const temFrameAncestors = /(^|;)\s*frame-ancestors\s/.test(csp);
const achados = [];
const achado = (nivel, titulo, detalhe, correcao = '') => achados.push({ nivel, titulo, detalhe, correcao });

// ---- Transporte ----
if (!ehHttps) {
  achado('alto', 'Site sem HTTPS',
    'A página final é servida por HTTP sem criptografia. Senhas, cookies e o próprio conteúdo podem ser lidos ou alterados no caminho.',
    'Instale um certificado TLS (ex.: Let\'s Encrypt) e redirecione todo o tráfego HTTP para HTTPS.');
}

// ---- Cabeçalhos de segurança ----
if (!status['content-security-policy'].presente) {
  achado('alto', 'Content-Security-Policy ausente',
    'Sem CSP, o navegador executa qualquer script injetado na página, o que facilita ataques de XSS.',
    "Content-Security-Policy: default-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'self'");
} else {
  const diretivaScript = (csp.match(/(?:^|;)\s*script-src\s+([^;]*)/) ?? csp.match(/(?:^|;)\s*default-src\s+([^;]*)/) ?? [])[1] ?? '';
  if (diretivaScript.includes("'unsafe-inline'") && !/'nonce-|'sha(256|384|512)-|'strict-dynamic'/.test(diretivaScript)) {
    achado('medio', "CSP permite scripts inline ('unsafe-inline')",
      'A política existe, mas aceita scripts escritos dentro do HTML. Isso anula boa parte da proteção contra XSS.',
      "Troque 'unsafe-inline' por nonces ou hashes: script-src 'self' 'nonce-<valor-aleatório>'");
  }
  if (diretivaScript.includes("'unsafe-eval'")) {
    achado('medio', "CSP permite eval ('unsafe-eval')",
      'Permite transformar texto em código JavaScript em tempo de execução, o que amplia o impacto de um XSS.',
      "Remova 'unsafe-eval' e evite eval(), new Function() e setTimeout com texto.");
  }
}

if (ehHttps) {
  if (!status['strict-transport-security'].presente) {
    achado('alto', 'Strict-Transport-Security (HSTS) ausente',
      'Sem HSTS, o primeiro acesso pode ser feito por HTTP e interceptado (ataque de downgrade / SSL stripping).',
      'Strict-Transport-Security: max-age=31536000; includeSubDomains');
  } else {
    const maxAge = Number((status['strict-transport-security'].valor.match(/max-age=(\d+)/i) ?? [])[1] ?? 0);
    if (maxAge < 15552000) {
      achado('baixo', 'HSTS com validade curta',
        `max-age=${maxAge} segundos (${Math.round(maxAge / 86400)} dias). O recomendado é pelo menos 6 meses; o ideal é 1 ano.`,
        'Strict-Transport-Security: max-age=31536000; includeSubDomains');
    }
  }
}

if (status['x-content-type-options'].valor.toLowerCase().trim() !== 'nosniff') {
  achado('medio', 'X-Content-Type-Options ausente ou inválido',
    'O navegador pode "adivinhar" o tipo de um arquivo e executar como script algo que deveria ser texto ou imagem.',
    'X-Content-Type-Options: nosniff');
}

if (!status['x-frame-options'].presente && !temFrameAncestors) {
  achado('medio', 'Proteção contra clickjacking ausente',
    'Nem X-Frame-Options nem a diretiva frame-ancestors da CSP estão definidos. Outro site pode exibir esta página dentro de um iframe invisível e induzir cliques.',
    "Content-Security-Policy: frame-ancestors 'self'   (ou X-Frame-Options: SAMEORIGIN)");
}

if (!status['referrer-policy'].presente) {
  achado('baixo', 'Referrer-Policy ausente',
    'O endereço completo da página (que pode ter parâmetros sensíveis) pode ser enviado a outros sites nos links.',
    'Referrer-Policy: strict-origin-when-cross-origin');
}

if (!status['permissions-policy'].presente) {
  achado('baixo', 'Permissions-Policy ausente',
    'Não há restrição de recursos do navegador (câmera, microfone, localização) para a página e iframes.',
    'Permissions-Policy: camera=(), microphone=(), geolocation=()');
}

if (status['x-xss-protection'].presente && !/^\s*0\s*$/.test(status['x-xss-protection'].valor)) {
  achado('info', 'X-XSS-Protection é obsoleto',
    'Navegadores modernos ignoram este cabeçalho e o filtro antigo já causou falhas. A proteção correta é a CSP.',
    'Remova o cabeçalho ou use X-XSS-Protection: 0');
}

// ---- Vazamento de informações ----
for (const nome of ['server', 'x-powered-by', 'x-aspnet-version', 'x-aspnetmvc-version', 'x-generator']) {
  const v = valor(nome);
  if (v && (/\d/.test(v) || nome !== 'server')) {
    achado('baixo', `Cabeçalho ${nome} revela tecnologia`,
      `Valor: "${v}". Saber a tecnologia e a versão ajuda um atacante a procurar falhas conhecidas.`,
      `Remova o cabeçalho ${nome} ou esconda a versão na configuração do servidor.`);
  }
}

// ---- CORS ----
if (valor('access-control-allow-origin').trim() === '*') {
  const comCredenciais = valor('access-control-allow-credentials').toLowerCase() === 'true';
  achado(comCredenciais ? 'alto' : 'info', 'CORS liberado para qualquer origem',
    comCredenciais
      ? 'Access-Control-Allow-Origin: * junto com Allow-Credentials: true é uma configuração perigosa.'
      : 'Qualquer site pode ler as respostas desta página pelo navegador. Só é aceitável para conteúdo público (ex.: CDN).',
    'Liste explicitamente as origens permitidas em Access-Control-Allow-Origin.');
}

// ---- Cookies ----
const cookies = [].concat(cab['set-cookie'] ?? []).map(String);
for (const cookie of cookies) {
  const nome = cookie.split('=')[0].trim() || '(sem nome)';
  const atributos = cookie.toLowerCase();
  const faltando = [];
  if (ehHttps && !/;\s*secure/.test(atributos)) faltando.push('Secure');
  if (!/;\s*httponly/.test(atributos)) faltando.push('HttpOnly');
  if (!/;\s*samesite=/.test(atributos)) faltando.push('SameSite');
  if (faltando.length) {
    achado(faltando.includes('Secure') ? 'medio' : 'baixo', `Cookie "${nome}" sem ${faltando.join(', ')}`,
      'Secure impede envio por HTTP; HttpOnly impede leitura por JavaScript (roubo via XSS); SameSite reduz CSRF. HttpOnly pode faltar de propósito se o cookie precisa ser lido pelo JavaScript.',
      `Set-Cookie: ${nome}=...; Secure; HttpOnly; SameSite=Lax`);
  }
}

// ---- Nota (A+ a F), parecida com a do securityheaders.com ----
const presente = (nome) => status[nome].presente;
const criticos = [
  presente('content-security-policy'),
  !ehHttps || presente('strict-transport-security'),
  status['x-content-type-options'].valor.toLowerCase().trim() === 'nosniff',
  presente('x-frame-options') || temFrameAncestors,
].filter(Boolean).length;
const importantes = [presente('referrer-policy'), presente('permissions-policy')].filter(Boolean).length;
const temProblemaCSP = achados.some((a) => a.titulo.startsWith('CSP permite'));

let nota;
if (criticos === 4) {
  if (importantes === 2) nota = temProblemaCSP ? 'A-' : 'A+';
  else if (importantes === 1) nota = temProblemaCSP ? 'B+' : 'A-';
  else nota = temProblemaCSP ? 'B' : 'B+';
} else if (criticos === 3) nota = importantes >= 1 ? 'B' : 'C+';
else if (criticos === 2) nota = 'C';
else if (criticos === 1) nota = 'D';
else nota = 'F';

// Sem HTTPS a nota não passa de D.
const ORDEM = ['A+', 'A', 'A-', 'B+', 'B', 'B-', 'C+', 'C', 'C-', 'D', 'F'];
if (!ehHttps && ORDEM.indexOf(nota) < ORDEM.indexOf('D')) nota = 'D';

const ordemNivel = { alto: 0, medio: 1, baixo: 2, info: 3 };
achados.sort((a, b) => ordemNivel[a.nivel] - ordemNivel[b.nivel]);

return [{
  json: {
    auditoria: {
      urlOriginal: dados.urlOriginal,
      urlFinal: dados.urlFinal,
      host: dados.host,
      ips: dados.ips,
      status: dados.status,
      statusMessage: dados.statusMessage,
      cadeia: dados.cadeia,
      parouNoLimite: dados.parouNoLimite,
      conteudoTruncado: dados.conteudoTruncado,
      tamanhoConteudo: dados.tamanhoConteudo,
      dataHora: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', dateStyle: 'long', timeStyle: 'short' }),
      ehHttps,
      nota,
      totalAlto: achados.filter((a) => a.nivel === 'alto').length,
      totalMedio: achados.filter((a) => a.nivel === 'medio').length,
      totalBaixo: achados.filter((a) => a.nivel === 'baixo').length,
      achados,
      statusCabecalhos: status,
      cabecalhos: cab,
      iaConfiguracao: textoDaIA('IA - configuração'),
      iaConteudo: textoDaIA('IA - conteúdo'),
    },
  },
}];

// ---- Biblioteca: HTML seguro ----
// Tudo o que vem do site analisado (cabeçalhos, HTML) ou da IA é texto NÃO confiável.
// Por isso tudo passa por escapar() antes de entrar no relatório: um site malicioso não consegue
// injetar HTML, scripts ou links no relatório mostrado na tela e enviado por e-mail.

function escapar(texto) {
  return String(texto ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Só deixa virar link um endereço http(s); qualquer outra coisa (javascript:, data:) vira texto.
function linkSeguro(url) {
  const texto = String(url ?? '');
  if (!/^https?:\/\//i.test(texto)) return escapar(texto);
  return `<a href="${escapar(texto)}" style="color:#1d4ed8;word-break:break-all">${escapar(texto)}</a>`;
}

// Formatação simples dentro de uma linha JÁ ESCAPADA: **negrito**, `código`.
function formatarLinha(textoEscapado) {
  return textoEscapado
    .replace(/`([^`]+)`/g, '<code style="background:#eef2f7;padding:1px 4px;border-radius:3px;font-family:Consolas,monospace;font-size:13px">$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
}

// Converte o Markdown da IA em HTML. Primeiro escapa, depois aplica a formatação,
// então nenhuma marcação vinda da IA ou do site chega crua ao relatório.
function markdownParaHtml(markdown) {
  const linhas = String(markdown ?? '').replace(/\r\n?/g, '\n').split('\n');
  const saida = [];
  let lista = null;
  let codigo = null;

  const fecharLista = () => {
    if (lista) { saida.push(`</${lista}>`); lista = null; }
  };

  for (const linha of linhas) {
    if (codigo !== null) {
      if (/^\s*```/.test(linha)) {
        saida.push(`<pre style="background:#0f172a;color:#e2e8f0;padding:10px;border-radius:6px;overflow-x:auto;font-family:Consolas,monospace;font-size:12px;white-space:pre-wrap">${escapar(codigo.join('\n'))}</pre>`);
        codigo = null;
      } else {
        codigo.push(linha);
      }
      continue;
    }
    if (/^\s*```/.test(linha)) { fecharLista(); codigo = []; continue; }

    const titulo = linha.match(/^\s*(#{1,6})\s+(.*)$/);
    if (titulo) {
      fecharLista();
      const nivel = titulo[1].length <= 2 ? 'h3' : 'h4';
      saida.push(`<${nivel} style="color:#0f172a;margin:16px 0 6px">${formatarLinha(escapar(titulo[2].replace(/\*\*/g, '')))}</${nivel}>`);
      continue;
    }

    const item = linha.match(/^\s*(?:([-*+])|(\d+)[.)])\s+(.*)$/);
    if (item) {
      const tipo = item[1] ? 'ul' : 'ol';
      if (lista !== tipo) { fecharLista(); saida.push(`<${tipo} style="margin:4px 0 8px;padding-left:22px">`); lista = tipo; }
      saida.push(`<li style="margin:3px 0">${formatarLinha(escapar(item[3]))}</li>`);
      continue;
    }

    if (!linha.trim()) { fecharLista(); continue; }
    if (/^\s*(-{3,}|\*{3,})\s*$/.test(linha)) { fecharLista(); continue; }
    fecharLista();
    saida.push(`<p style="margin:6px 0">${formatarLinha(escapar(linha.trim()))}</p>`);
  }
  if (codigo !== null) saida.push(`<pre style="background:#0f172a;color:#e2e8f0;padding:10px;border-radius:6px;white-space:pre-wrap">${escapar(codigo.join('\n'))}</pre>`);
  fecharLista();
  return saida.join('\n');
}
// ---- fim da biblioteca ----

// Nó "Gerar relatório": monta o relatório em HTML (o mesmo para a tela e para o e-mail).
// Só usa estilos inline, que funcionam no Outlook e dentro da página do formulário.
const a = $input.first().json.auditoria;

const CORES_NOTA = { 'A+': '#15803d', A: '#15803d', 'A-': '#15803d', 'B+': '#1d4ed8', B: '#1d4ed8', 'B-': '#1d4ed8', 'C+': '#b45309', C: '#b45309', 'C-': '#b45309', D: '#b91c1c', F: '#b91c1c' };
const NIVEIS = {
  alto: { rotulo: 'Alto', cor: '#b91c1c', fundo: '#fef2f2' },
  medio: { rotulo: 'Médio', cor: '#b45309', fundo: '#fffbeb' },
  baixo: { rotulo: 'Baixo', cor: '#1d4ed8', fundo: '#eff6ff' },
  info: { rotulo: 'Info', cor: '#475569', fundo: '#f8fafc' },
};
const NOMES_CABECALHOS = {
  'content-security-policy': 'Content-Security-Policy',
  'strict-transport-security': 'Strict-Transport-Security',
  'x-content-type-options': 'X-Content-Type-Options',
  'x-frame-options': 'X-Frame-Options',
  'referrer-policy': 'Referrer-Policy',
  'permissions-policy': 'Permissions-Policy',
  'cross-origin-opener-policy': 'Cross-Origin-Opener-Policy',
  'cross-origin-embedder-policy': 'Cross-Origin-Embedder-Policy',
  'cross-origin-resource-policy': 'Cross-Origin-Resource-Policy',
  'x-permitted-cross-domain-policies': 'X-Permitted-Cross-Domain-Policies',
};

const caixa = (titulo, conteudo) => `
  <div style="background:#ffffff;border:1px solid #e2e8f0;border-radius:8px;padding:16px 18px;margin:0 0 16px">
    <h2 style="font-size:18px;color:#0f172a;margin:0 0 12px">${titulo}</h2>
    ${conteudo}
  </div>`;

// Selos só dos 6 cabeçalhos que todo site deveria ter (COEP/CORP etc. dependem do caso).
function selos() {
  return Object.entries(NOMES_CABECALHOS).slice(0, 6).map(([chave, nome]) => {
    const ok = a.statusCabecalhos[chave]?.presente;
    return `<span style="display:inline-block;margin:2px 4px 2px 0;padding:3px 8px;border-radius:4px;font-size:12px;color:#fff;background:${ok ? '#15803d' : '#b91c1c'}">${ok ? '✓' : '✗'} ${escapar(nome)}</span>`;
  }).join('');
}

function listaAchados() {
  if (!a.achados.length) return '<p style="margin:0">Nenhum problema encontrado nos cabeçalhos e cookies.</p>';
  return a.achados.map((x) => {
    const n = NIVEIS[x.nivel];
    return `
      <div style="border-left:4px solid ${n.cor};background:${n.fundo};padding:10px 12px;margin:0 0 10px;border-radius:0 6px 6px 0">
        <div><span style="display:inline-block;font-size:11px;font-weight:bold;color:#fff;background:${n.cor};padding:2px 6px;border-radius:3px;margin-right:6px">${n.rotulo}</span><strong style="color:#0f172a">${escapar(x.titulo)}</strong></div>
        <div style="margin-top:6px;color:#334155">${escapar(x.detalhe)}</div>
        ${x.correcao ? `<div style="margin-top:6px"><span style="color:#475569;font-size:13px">Como corrigir:</span><pre style="background:#0f172a;color:#e2e8f0;padding:8px 10px;border-radius:6px;margin:4px 0 0;font-family:Consolas,monospace;font-size:12px;white-space:pre-wrap;word-break:break-all">${escapar(x.correcao)}</pre></div>` : ''}
      </div>`;
  }).join('');
}

function analiseIA(resultado) {
  if (!resultado.ok) return `<p style="margin:0;color:#b45309">${escapar(resultado.texto)}</p>`;
  return `<div style="color:#334155;font-size:14px;line-height:1.5">${markdownParaHtml(resultado.texto)}</div>`;
}

function tabelaCabecalhos() {
  const linhas = Object.entries(a.cabecalhos).flatMap(([nome, valor]) =>
    (Array.isArray(valor) ? valor : [valor]).map((v) => `
      <tr>
        <td style="padding:6px 8px;border-bottom:1px solid #e2e8f0;font-weight:bold;vertical-align:top;white-space:nowrap;color:${NOMES_CABECALHOS[nome] ? '#15803d' : '#0f172a'}">${escapar(nome)}</td>
        <td style="padding:6px 8px;border-bottom:1px solid #e2e8f0;font-family:Consolas,monospace;font-size:12px;word-break:break-all">${escapar(v)}</td>
      </tr>`));
  if (!linhas.length) return '<p style="margin:0">Nenhum cabeçalho recebido.</p>';
  return `<table style="width:100%;border-collapse:collapse;font-size:13px">${linhas.join('')}</table>`;
}

function cadeiaRedirecionamentos() {
  if (!a.cadeia || a.cadeia.length <= 1) return '';
  const itens = a.cadeia.map((c) => `<li style="margin:3px 0"><code>${escapar(c.status)}</code> ${linkSeguro(c.url)}</li>`).join('');
  const aviso = a.parouNoLimite ? '<p style="margin:8px 0 0;color:#b45309">O site ainda pedia outro redirecionamento; o scanner parou no limite de 5.</p>' : '';
  return caixa('Redirecionamentos', `<ol style="margin:0;padding-left:22px">${itens}</ol>${aviso}`);
}

const observacoes = [];
if (a.conteudoTruncado) observacoes.push(`A página tem ${a.tamanhoConteudo.toLocaleString('pt-BR')} caracteres; a IA analisou só o começo.`);
if (a.status >= 400) observacoes.push(`O site respondeu com erro ${a.status}. A análise vale para a página de erro, não para o conteúdo normal.`);

const html = `<div style="font-family:Segoe UI,Arial,sans-serif;background:#f1f5f9;padding:16px;color:#0f172a">
<div style="max-width:900px;margin:0 auto">
  <div style="background:#0f172a;color:#fff;padding:20px;border-radius:8px 8px 0 0;text-align:center">
    <div style="font-size:24px;font-weight:bold">Relatório de segurança do site</div>
    <div style="font-size:13px;color:#cbd5e1;margin-top:4px">Scanner de Segurança Web · análise passiva, sem ataques</div>
  </div>
  <div style="height:16px"></div>

  ${caixa('Resumo', `
    <table style="width:100%;border-collapse:collapse"><tr>
      <td style="width:110px;vertical-align:top;padding-right:14px">
        <div style="width:96px;height:96px;line-height:96px;text-align:center;font-size:44px;font-weight:bold;color:#fff;border-radius:8px;background:${CORES_NOTA[a.nota] ?? '#b91c1c'}">${escapar(a.nota)}</div>
      </td>
      <td style="vertical-align:top;font-size:14px">
        <table style="border-collapse:collapse">
          <tr><td style="padding:2px 10px 2px 0;color:#475569">Site:</td><td>${linkSeguro(a.urlOriginal)}</td></tr>
          ${a.urlFinal !== a.urlOriginal ? `<tr><td style="padding:2px 10px 2px 0;color:#475569">Página final:</td><td>${linkSeguro(a.urlFinal)}</td></tr>` : ''}
          <tr><td style="padding:2px 10px 2px 0;color:#475569">IP:</td><td>${escapar((a.ips ?? []).join(', '))}</td></tr>
          <tr><td style="padding:2px 10px 2px 0;color:#475569">Resposta:</td><td>${escapar(a.status)} ${escapar(a.statusMessage)}</td></tr>
          <tr><td style="padding:2px 10px 2px 0;color:#475569">Data:</td><td>${escapar(a.dataHora)}</td></tr>
          <tr><td style="padding:2px 10px 2px 0;color:#475569">Problemas:</td><td><strong style="color:#b91c1c">${a.totalAlto} alto</strong> · <strong style="color:#b45309">${a.totalMedio} médio</strong> · <strong style="color:#1d4ed8">${a.totalBaixo} baixo</strong></td></tr>
        </table>
      </td>
    </tr></table>
    <div style="margin-top:12px">${selos()}</div>
    ${observacoes.map((o) => `<p style="margin:8px 0 0;color:#b45309;font-size:13px">⚠ ${escapar(o)}</p>`).join('')}
  `)}

  ${caixa('Achados automáticos (cabeçalhos e cookies)', listaAchados())}
  ${caixa('Análise da IA: configuração (cabeçalhos e cookies)', analiseIA(a.iaConfiguracao))}
  ${caixa('Análise da IA: conteúdo da página (HTML e JavaScript)', analiseIA(a.iaConteudo))}
  ${cadeiaRedirecionamentos()}
  ${caixa('Cabeçalhos recebidos', tabelaCabecalhos())}

  <div style="font-size:12px;color:#64748b;text-align:center;padding:8px 12px 4px;line-height:1.5">
    Análise automática e passiva: o scanner fez uma única leitura da página, como um navegador, sem testar ataques.
    A nota vem só dos cabeçalhos reais; a análise da IA é complementar e pode conter erros, então confirme antes de corrigir.
    Para uma avaliação completa, faça um teste de intrusão autorizado.
  </div>
</div>
</div>`;

return [{
  json: {
    html,
    assunto: `Relatório de segurança: ${a.host} (nota ${a.nota})`,
    nota: a.nota,
    host: a.host,
  },
}];

// ---- Biblioteca: HTML seguro ----
// Tudo o que vem do site analisado (cabeçalhos, HTML) ou da IA é texto NÃO confiável.
// Por isso tudo passa por escapar() antes de entrar no relatório: um site malicioso não consegue
// injetar HTML, scripts ou links no relatório mostrado na tela e enviado por e-mail.

function escapar(texto) {
  return String(texto ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Só deixa virar link um endereço http(s); qualquer outra coisa (javascript:, data:) vira texto.
function linkSeguro(url) {
  const texto = String(url ?? '');
  if (!/^https?:\/\//i.test(texto)) return escapar(texto);
  return `<a href="${escapar(texto)}" style="color:#1d4ed8;word-break:break-all">${escapar(texto)}</a>`;
}

// Formatação simples dentro de uma linha JÁ ESCAPADA: **negrito**, `código`.
function formatarLinha(textoEscapado) {
  return textoEscapado
    .replace(/`([^`]+)`/g, '<code style="background:#eef2f7;padding:1px 4px;border-radius:3px;font-family:Consolas,monospace;font-size:13px">$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
}

// Converte o Markdown da IA em HTML. Primeiro escapa, depois aplica a formatação,
// então nenhuma marcação vinda da IA ou do site chega crua ao relatório.
function markdownParaHtml(markdown) {
  const linhas = String(markdown ?? '').replace(/\r\n?/g, '\n').split('\n');
  const saida = [];
  let lista = null;
  let codigo = null;

  const fecharLista = () => {
    if (lista) { saida.push(`</${lista}>`); lista = null; }
  };

  for (const linha of linhas) {
    if (codigo !== null) {
      if (/^\s*```/.test(linha)) {
        saida.push(`<pre style="background:#0f172a;color:#e2e8f0;padding:10px;border-radius:6px;overflow-x:auto;font-family:Consolas,monospace;font-size:12px;white-space:pre-wrap">${escapar(codigo.join('\n'))}</pre>`);
        codigo = null;
      } else {
        codigo.push(linha);
      }
      continue;
    }
    if (/^\s*```/.test(linha)) { fecharLista(); codigo = []; continue; }

    const titulo = linha.match(/^\s*(#{1,6})\s+(.*)$/);
    if (titulo) {
      fecharLista();
      const nivel = titulo[1].length <= 2 ? 'h3' : 'h4';
      saida.push(`<${nivel} style="color:#0f172a;margin:16px 0 6px">${formatarLinha(escapar(titulo[2].replace(/\*\*/g, '')))}</${nivel}>`);
      continue;
    }

    const item = linha.match(/^\s*(?:([-*+])|(\d+)[.)])\s+(.*)$/);
    if (item) {
      const tipo = item[1] ? 'ul' : 'ol';
      if (lista !== tipo) { fecharLista(); saida.push(`<${tipo} style="margin:4px 0 8px;padding-left:22px">`); lista = tipo; }
      saida.push(`<li style="margin:3px 0">${formatarLinha(escapar(item[3]))}</li>`);
      continue;
    }

    if (!linha.trim()) { fecharLista(); continue; }
    if (/^\s*(-{3,}|\*{3,})\s*$/.test(linha)) { fecharLista(); continue; }
    fecharLista();
    saida.push(`<p style="margin:6px 0">${formatarLinha(escapar(linha.trim()))}</p>`);
  }
  if (codigo !== null) saida.push(`<pre style="background:#0f172a;color:#e2e8f0;padding:10px;border-radius:6px;white-space:pre-wrap">${escapar(codigo.join('\n'))}</pre>`);
  fecharLista();
  return saida.join('\n');
}
// ---- fim da biblioteca ----

// Nó "Página de erro": mostra na tela por que o site não foi analisado
// (endereço recusado, domínio inexistente, certificado inválido, site fora do ar etc.).
const entrada = $input.first().json;
let motivo = entrada.motivo;

if (!motivo) {
  const tecnico = String(entrada.error?.message ?? entrada.error ?? entrada.message ?? 'erro desconhecido');
  const t = tecnico.toLowerCase();
  if (t.includes('certificate') || t.includes('self signed') || t.includes('ssl') || t.includes('tls')) {
    motivo = 'O certificado HTTPS do site é inválido, expirado ou não confiável. Isso já é um problema de segurança: o navegador também mostraria um alerta para os visitantes.';
  } else if (t.includes('enotfound') || t.includes('eai_again')) {
    motivo = 'O domínio não foi encontrado.';
  } else if (t.includes('timeout') || t.includes('timedout') || t.includes('etimedout')) {
    motivo = 'O site demorou demais para responder (mais de 20 segundos).';
  } else if (t.includes('econnrefused') || t.includes('econnreset') || t.includes('socket hang up')) {
    motivo = 'O site recusou ou encerrou a conexão.';
  } else {
    motivo = 'Não foi possível acessar o site.';
  }
  motivo += ` Detalhe técnico: ${tecnico.slice(0, 300)}`;
}

const html = `<div style="font-family:Segoe UI,Arial,sans-serif;background:#f1f5f9;padding:16px;color:#0f172a">
  <div style="max-width:640px;margin:40px auto;background:#fff;border:1px solid #e2e8f0;border-left:5px solid #b91c1c;border-radius:8px;padding:20px 22px">
    <div style="font-size:20px;font-weight:bold;margin-bottom:8px">Não foi possível analisar este site</div>
    <p style="margin:0 0 12px;color:#334155;line-height:1.5">${escapar(motivo)}</p>
    <p style="margin:0;color:#475569;font-size:13px">Endereço informado: <code>${escapar($('Configuração').first().json.url ?? '')}</code></p>
    <p style="margin:16px 0 0;color:#475569;font-size:13px">Recarregue a página (F5) para tentar outro endereço.</p>
  </div>
</div>`;

return [{ json: { html } }];
